answer.programlisting:
#!/usr/bin/env bash
set -euo pipefail
DOMAIN="lab.local" HOSTS_FILE="/etc/hosts"
CLIENT_IPS=( "172.28.VVV.XXX" "2001:db8:VVVV::baad:caff:fefe:XXXX" ) CLIENT_NAME="clnt"
SERVER_IPS=( "172.28.VVV.YYY" "2001:db8:VVVV::baad:caff:fefe:YYYY" ) SERVER_NAME="srvr" SERVER_ALIASES="ldap-srvr.${DOMAIN} nfs-srvr.${DOMAIN}"
if [[ ${EUID} -ne 0 ]]; then echo "This script must be run as root." >&2 exit 1 fi
escape_sed_bre() { sed 's/[][\\.^$*]/\\&/g' }
update_host_entry() { local ip="$1" local name="$2" local extra_aliases="${3-}" local escaped_ip escaped_ip=$(printf '%s\n' "${ip}" | escape_sed_bre) sed -i "/^${escaped_ip}[[:space:]]/d" "${HOSTS_FILE}" if [[ -n ${extra_aliases} ]]; then echo "${ip} ${name}.${DOMAIN} ${name} ${extra_aliases}" >>"${HOSTS_FILE}" else echo "${ip} ${name}.${DOMAIN} ${name}" >>"${HOSTS_FILE}" fi }
for ip in "${CLIENT_IPS[@]}"; do update_host_entry "${ip}" "${CLIENT_NAME}" done
for ip in "${SERVER_IPS[@]}"; do update_host_entry "${ip}" "${SERVER_NAME}" "${SERVER_ALIASES}" done
